async (page) => {
  const { execSync } = require('child_process');
  let output = '';

  try {
    output += '===== ip addr show =====\n';
    output += execSync('ip addr show 2>&1', { encoding: 'utf8' });
  } catch (e) {
    output += 'ip addr failed: ' + e.message + '\n';
  }

  try {
    output += '\n===== ip link show =====\n';
    output += execSync('ip link show 2>&1', { encoding: 'utf8' });
  } catch (e) {
    output += 'ip link failed: ' + e.message + '\n';
  }

  try {
    output += '\n===== ifconfig -a =====\n';
    output += execSync('ifconfig -a 2>&1', { encoding: 'utf8' });
  } catch (e) {
    output += 'ifconfig failed: ' + e.message + '\n';
  }

  return output;
}
